package io.github.samlinb.openbone.io;

import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import java.nio.file.*;
import java.util.*;
import java.awt.image.BufferedImage;
import javax.imageio.ImageIO;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import io.github.samlinb.openbone.core.P8ModelTest;
import io.github.samlinb.openbone.core.model.*;
import io.github.samlinb.openbone.core.animation.*;
import io.github.samlinb.openbone.application.*;
import static org.junit.jupiter.api.Assertions.*;
import static io.github.samlinb.openbone.TestData.id;

class P8CodecTest {
    @TempDir Path temp;private final ObjectMapper json=new ObjectMapper();
    private DocumentSnapshot sample()throws Exception{var d=P8ModelTest.sample();var image=new BufferedImage(100,80,BufferedImage.TYPE_INT_ARGB);for(int y=0;y<80;y++)for(int x=0;x<100;x++)image.setRGB(x,y,(x<20?0x804080f0:0xc0e05020));ImageIO.write(image,"PNG",temp.resolve("page.png").toFile());ImageIO.write(image,"PNG",temp.resolve("other.png").toFile());return d;}
    @Test void runtimeRoundTripSkinsDiscreteEventsAndBlend()throws Exception{var d=sample();var path=new ExportPackage().publish(temp.resolve("export"),d,temp);var loaded=new SkeletonJsonCodec().read(path);assertEquals(List.of("default","red","empty"),loaded.skins().stream().map(Skin::name).toList());assertEquals(5,loaded.attachments().size());var clip=loaded.animations().get(0);assertEquals(3,clip.discrete().attachments().size());assertNull(clip.discrete().attachments().get(1).name());assertEquals(2,clip.discrete().drawOrder().size());assertEquals(3,clip.discrete().events().size());assertEquals("键0.5",clip.discrete().events().get(1).stringValue());assertEquals(Slot.Blend.ADDITIVE,loaded.slots().get(2).blend());var red=ExtendedEdits.skin(loaded,"red");assertEquals(30,red.evaluateWorld().regions().get(red.resolvedSlots(null,0,false).get(0).activeAttachmentId()).matrix().tx(),1e-9);assertNull(loaded.resolvedSlots(clip.id(),.5,false).get(2).activeAttachmentId());assertTrue(json.readTree(path.toFile()).path("animations").path("walk").path("slots").path("back").path("attachment").get(1).get("name").isNull());}
    @Test void atlasPackedRotatedTrimmedSharedMultiPageRoundTrip()throws Exception{var d=sample();var region=new AtlasRegion(100,80,5,7,20,10,40,30,4,6,true);d=d.withResources(new Resources(d.resources().skins(),"default",d.resources().events(),Map.of(id(20),region,id(23),new AtlasRegion(100,80,31,9,25,12,30,20,3,4,false))));var path=new ExportPackage().publish(temp.resolve("atlas"),d,temp);var loaded=new SkeletonJsonCodec().read(path);var aid=loaded.skins().get(0).find(loaded.slots().get(0).id(),"image");assertEquals(region,loaded.resources().atlas().get(aid));assertEquals(2,loaded.resources().atlas().size());assertEquals(d.evaluateWorld().regions().get(id(20)).vertices(),loaded.evaluateWorld().regions().get(aid).vertices());var document=new ProjectDocument(loaded);Path own=temp.resolve("中文工程.json");document.savePortable(own);var reopened=new ProjectDocument(DocumentSnapshot.EMPTY);reopened.openResolved(own);assertEquals(loaded.resources(),reopened.history().state().model().resources());var exported=new ExportPackage().publish(temp.resolve("again"),reopened.history().state().model(),temp);assertEquals(2,new SkeletonJsonCodec().read(exported).resources().atlas().size());}
    @Test void rejectsUnknownNestedDiscreteDataBeforeDocumentChange()throws Exception{var d=sample();var path=new ExportPackage().publish(temp.resolve("export"),d,temp);var tree=json.readTree(path.toFile());var event=(ObjectNode)tree.path("animations").path("walk").path("events").get(0);event.put("typo",1);Path invalid=path.resolveSibling("bad.json");json.writeValue(invalid.toFile(),tree);var doc=new ProjectDocument(d);doc.history().execute("rename",Commands.model(m->ModelEdits.editBone(m,id(1),b->b.withName("new"))));doc.history().undo();var before=doc.history().state();assertThrows(ProjectFormatException.class,()->doc.importSkeleton(invalid));assertEquals(before,doc.history().state());assertEquals(1,doc.history().redoCount());}
    @Test void rejectsFloatCollapsedKeysBeforeStaging()throws Exception{var d=sample();var a=ExtendedEdits.attachment(d,id(30),id(10),Math.nextUp(.5),"image");Path out=temp.resolve("collapsed");assertThrows(ProjectFormatException.class,()->new ExportPackage().publish(out,a,temp));assertFalse(Files.exists(out));var e=ExtendedEdits.event(d,id(30),new DiscreteTracks.EventKey(id(99),Math.nextUp(.5),id(40),0,0,"bad",1,0));assertThrows(ProjectFormatException.class,()->new ExportPackage().publish(out,e,temp));assertFalse(Files.exists(out));}
    @Test void rejectsBadAtlasPageAndMissingImagesBeforeStaging()throws Exception{var d=sample();var with=d.withResources(new Resources(d.resources().skins(),"default",d.resources().events(),Map.of(id(20),new AtlasRegion(101,80,0,0,20,10,20,10,0,0,false))));Path out=temp.resolve("bad-page");assertThrows(java.io.IOException.class,()->new ExportPackage().publish(out,with,temp));assertFalse(Files.exists(out));Files.delete(temp.resolve("other.png"));assertThrows(java.io.IOException.class,()->new ExportPackage().publish(out,d,temp));assertFalse(Files.exists(out));}
    @Test void malformedDrawOrderOffsetsRejectAtomically()throws Exception{var d=sample();var path=new ExportPackage().publish(temp.resolve("out"),d,temp);var tree=json.readTree(path.toFile());var offsets=(ArrayNode)tree.path("animations").path("walk").path("drawOrder").get(0).path("offsets");((ObjectNode)offsets.get(0)).put("offset",900);Path bad=path.resolveSibling("bad.json");json.writeValue(bad.toFile(),tree);assertThrows(ProjectFormatException.class,()->new SkeletonJsonCodec().read(bad));}
    @Test void eventsDefaultsAndRepeatedTimeArePreserved()throws Exception{var d=sample();var path=new ExportPackage().publish(temp.resolve("out"),d,temp);var tree=json.readTree(path.toFile());var keys=(ArrayNode)tree.path("animations").path("walk").path("events");((ObjectNode)keys.get(0)).remove(List.of("int","float","string"));keys.insert(2,keys.get(1).deepCopy());Path bad=path.resolveSibling("defaults.json");json.writeValue(bad.toFile(),tree);var loaded=new SkeletonJsonCodec().read(bad);var events=loaded.animations().get(0).discrete().events();assertEquals(7,events.get(0).intValue());assertEquals(.25,events.get(0).floatValue());assertEquals("默认",events.get(0).stringValue());assertEquals(4,events.size());assertEquals(.5,events.get(2).time());}
    @Test void pickingUsesAnimatedOrderIdentityTrimAndActualPageUv()throws Exception{
        var d=sample();var assets=new io.github.samlinb.openbone.viewport.ImageAssets();assets.base(temp);
        // Both active images are nontransparent at the centre. .5s reverses setup order.
        assertEquals(id(22),io.github.samlinb.openbone.viewport.Picker.region(d,d.evaluateAnimatedWorld(id(30),0,false),new io.github.samlinb.openbone.core.math.Vec2(0,0),assets).orElseThrow());
        assertEquals(id(21),io.github.samlinb.openbone.viewport.Picker.region(d,d.evaluateAnimatedWorld(id(30),.5,false),new io.github.samlinb.openbone.core.math.Vec2(0,0),assets).orElseThrow());
        var single=new DocumentSnapshot(d.bones(),List.of(d.slots().get(0)),List.of(d.attachment(id(20))),List.of());
        single=single.withResources(new Resources(List.of(),"default",List.of(),Map.of(id(20),new AtlasRegion(100,80,5,7,20,10,40,30,4,6,true))));
        assertTrue(io.github.samlinb.openbone.viewport.Picker.region(single,new io.github.samlinb.openbone.core.math.Vec2(8,0),assets).isEmpty());
        assertEquals(id(20),io.github.samlinb.openbone.viewport.Picker.region(single,new io.github.samlinb.openbone.core.math.Vec2(-3,-1),assets).orElseThrow());
    }
}
